                        break;
                case WAVE_FORMAT_MP3:
                        codecid = GF_CODECID_MPEG_AUDIO;
                        unframed = GF_TRUE;
                        break;
                case WAVE_FORMAT_AAC_ADTS:
                        codecid = GF_CODECID_AAC_MPEG4;
                        unframed = GF_TRUE;
                        break;
                case WAVE_FORMAT_AAC:
                        codecid = GF_CODECID_AAC_MPEG4;
                        break;
